import{_ as e,a}from"./chunks/setup-vrchat-osc.OjexboPL.js";import{_ as r}from"./chunks/ts-mic-privacy.DXgfNaDe.js";import{_ as d,o,c as n,ag as h}from"./chunks/framework.DTisvaUJ.js";const f=JSON.parse('{"title":"문제 해결 — 소리·인식 문제","description":"Mutelink 읽기 소리·마이크 인식·VRChat 채팅창 전송 문제를 순서대로 확인합니다.","frontmatter":{"title":"문제 해결 — 소리·인식 문제","description":"Mutelink 읽기 소리·마이크 인식·VRChat 채팅창 전송 문제를 순서대로 확인합니다.","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/ko/help/troubleshooting"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:title","content":"문제 해결 — 소리·인식 문제 | Mutelink"}],["meta",{"property":"og:description","content":"Mutelink 읽기 소리·마이크 인식·VRChat 채팅창 전송 문제를 순서대로 확인합니다."}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/ko/help/troubleshooting"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/home-banner.png"}],["meta",{"property":"og:image:width","content":"1400"}],["meta",{"property":"og:image:height","content":"547"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"문제 해결 — 소리·인식 문제 | Mutelink"}],["meta",{"name":"twitter:description","content":"Mutelink 읽기 소리·마이크 인식·VRChat 채팅창 전송 문제를 순서대로 확인합니다."}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/home-banner.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/help/troubleshooting"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/help/troubleshooting"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/help/troubleshooting"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/help/troubleshooting"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/help/troubleshooting"}]]},"headers":[],"relativePath":"ko/help/troubleshooting.md","filePath":"ko/help/troubleshooting.md"}'),i={name:"ko/help/troubleshooting.md"};function l(s,t,u,g,b,p){return o(),n("div",null,[...t[0]||(t[0]=[h('<h1 id="困ったときの対処" tabindex="-1">문제 해결 <a class="header-anchor" href="#困ったときの対処" aria-label="Permalink to &quot;문제 해결 {#困ったときの対処}&quot;">​</a></h1><p>위에서 아래로 확인하세요. 해당 문제가 없으면 설정 &gt; 기타 &gt; 앱 정보 &gt; 문제·요청 보내기로 알려 주세요.</p><h2 id="読み上げの声が出ない" tabindex="-1">읽기 소리가 안 나옴 <a class="header-anchor" href="#読み上げの声が出ない" aria-label="Permalink to &quot;읽기 소리가 안 나옴 {#読み上げの声が出ない}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>확인할 내용</th><th>해결 방법</th></tr></thead><tbody><tr><td>메인 합성 음성 버튼</td><td>꺼져 있으면 읽지 않으므로 켜기</td></tr><tr><td>목소리 선택</td><td>출력 언어에 VOICEVOX·Irodori-TTS·Qwen3-TTS 선택. 없음은 채팅창만 전송</td></tr><tr><td>다운로드 완료</td><td>설정 &gt; 기타 &gt; 모델과 용량 확인. VOICEVOX는 캐릭터도 선택</td></tr><tr><td>출력 장치·볼륨</td><td>설정 &gt; 보내기 &gt; 읽기 기본 &gt; 스피커에서 장치별 볼륨 확인</td></tr><tr><td>번역문 읽기</td><td><a href="/Mutelink-releases/ko/about/supporter">후원판</a> 필요. 없으면 번역문은 채팅창만 전송</td></tr><tr><td>지원 언어</td><td>VOICEVOX·Irodori는 일본어, Qwen은 10개 언어. 읽을 수 없으면 채팅창만 전송</td></tr><tr><td>VRAM 부족으로 AI 음성 꺼짐</td><td>읽기가 자동 해제되어 채팅창만 사용합니다. 자동 복구하지 않으므로 여유가 생기면 TTS 버튼을 켜면 같은 목소리로 돌아옵니다</td></tr></tbody></table><h2 id="vrchatの相手に声が届かない" tabindex="-1">VRChat 상대가 소리를 못 들음 <a class="header-anchor" href="#vrchatの相手に声が届かない" aria-label="Permalink to &quot;VRChat 상대가 소리를 못 들음 {#vrchatの相手に声が届かない}&quot;">​</a></h2><p>내 스피커에서는 들리지만 상대가 못 듣는 경우입니다.</p><table tabindex="0"><thead><tr><th>확인할 내용</th><th>해결 방법</th></tr></thead><tbody><tr><td>가상 케이블 설치</td><td>Windows 소리에 CABLE Input/Output 확인. 없으면 <a href="/Mutelink-releases/ko/guide/getting-started#_1-vb-audio-virtual-cableを入れる">설치</a></td></tr><tr><td>Mutelink 출력에 CABLE Input</td><td>설정 &gt; 보내기 &gt; 읽기 기본 &gt; 스피커에서 선택. 없으면 목록 갱신 또는 앱 재시작</td></tr><tr><td>VRChat 마이크가 CABLE Output인지</td><td>VRChat 설정 &gt; 오디오 확인</td></tr><tr><td><strong>VRChat 마이크 재선택</strong></td><td>CABLE Output이어도 다른 장치로 바꿨다 돌아오세요. 시작 시 장치를 유지하므로 나중에 설치·변경한 케이블은 다시 선택해야 합니다. VRChat 재시작도 가능</td></tr><tr><td>VRChat 음소거</td><td>VRChat 안에서 마이크 음소거 해제</td></tr><tr><td>Mutelink 마이크가 CABLE Output인지</td><td>실제 말하는 마이크로 선택</td></tr></tbody></table><p><img src="'+e+'" alt="VRChat 마이크 CABLE Output 확인"></p><h2 id="自分には読み上げが聞こえない" tabindex="-1">내게 읽기 소리가 안 들림 <a class="header-anchor" href="#自分には読み上げが聞こえない" aria-label="Permalink to &quot;내게 읽기 소리가 안 들림 {#自分には読み上げが聞こえない}&quot;">​</a></h2><p>CABLE Input만 선택하면 상대만 듣습니다. 설정 &gt; 보내기 &gt; 읽기 기본 &gt; 스피커에서 CABLE Input과 내 스피커·헤드폰을 모두 고르세요. 장치별 볼륨을 조절할 수 있습니다.</p><h2 id="vrchatに文字が出ない" tabindex="-1">VRChat에 글이 안 나옴 <a class="header-anchor" href="#vrchatに文字が出ない" aria-label="Permalink to &quot;VRChat에 글이 안 나옴 {#vrchatに文字が出ない}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>확인할 내용</th><th>해결 방법</th></tr></thead><tbody><tr><td>OSC 활성화</td><td>원형 메뉴 &gt; Options &gt; OSC &gt; Enabled</td></tr><tr><td>메인 채팅창 버튼</td><td>꺼져 있으면 전송하지 않음</td></tr><tr><td>전송했는지</td><td>자동 전송이 꺼져 있으면 인식만으로 보내지 않으므로 전송 조작</td></tr><tr><td>음성 시작 후 표시 설정</td><td>설정 &gt; 보내기 &gt; 읽기 기본에서 선택 시 발성이 시작될 때까지 최대 8초 대기</td></tr><tr><td>VRChat 채팅창 숨김</td><td>VRChat 설정 확인</td></tr></tbody></table><p><img src="'+a+'" alt="VRChat OSC Enabled 확인"></p><h2 id="音声認識が動かない・途切れる" tabindex="-1">음성 인식이 안 되거나 끊김 <a class="header-anchor" href="#音声認識が動かない・途切れる" aria-label="Permalink to &quot;음성 인식이 안 되거나 끊김 {#音声認識が動かない・途切れる}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>확인할 내용</th><th>해결 방법</th></tr></thead><tbody><tr><td>인식 켜짐</td><td>메인 음성 인식 버튼 켜기</td></tr><tr><td>올바른 마이크</td><td>설정 &gt; 말하기 &gt; 마이크에서 실제 마이크 선택</td></tr><tr><td>Windows 마이크 권한</td><td>설정 &gt; 개인정보 및 보안 &gt; 마이크에서 데스크톱 앱 마이크 접근 허용</td></tr><tr><td>모델 다운로드</td><td>로컬 엔진은 최초 다운로드 필요. 설정 &gt; 기타 &gt; 모델과 용량 확인</td></tr><tr><td>인식 서비스 연결 불가</td><td>네트워크·제공자 문제로 클라우드가 끊길 수 있습니다. 설정 &gt; 말하기 &gt; 언어와 인식에서 로컬로 변경(<a href="/Mutelink-releases/ko/compare/speech-recognition">비교</a>)</td></tr><tr><td>언어 지원</td><td>Parakeet 일본어 TDT·Haas-ja는 일본어만, Parakeet 영어는 일본어 미지원</td></tr><tr><td>특정 단어만 누락</td><td>제외 단어 설정 확인</td></tr></tbody></table><p><img src="'+r+'" alt="Windows 마이크 개인정보 설정"></p><h2 id="ダウンロードが失敗する" tabindex="-1">다운로드 실패 <a class="header-anchor" href="#ダウンロードが失敗する" aria-label="Permalink to &quot;다운로드 실패 {#ダウンロードが失敗する}&quot;">​</a></h2><p>화면에 실패 원인이 표시됩니다. 받은 부분은 남아 있으므로 다시 다운로드를 누르면 이어받습니다.</p><table tabindex="0"><thead><tr><th>표시</th><th>해결 방법</th></tr></thead><tbody><tr><td>통신 중단·멈춤</td><td>네트워크 확인 후 재시도</td></tr><tr><td>배포처 파일 없음</td><td>위치가 바뀌었을 수 있으니 앱 업데이트(설정 &gt; 기타 &gt; 앱 정보)</td></tr><tr><td>서버 응답 없음</td><td>잠시 후 다시 시도</td></tr><tr><td>파일 손상</td><td>자동 삭제되었으므로 다시 다운로드</td></tr><tr><td>저장 공간 부족</td><td>공간 확보 후 재시도. 설정 &gt; 기타 &gt; 모델과 용량에서 확인</td></tr></tbody></table><p>부분 다운로드는 설정 &gt; 기타 &gt; 모델과 용량에서 지울 수 있습니다.</p><h2 id="irodori-tts・qwen3-ttsが動かない" tabindex="-1">Irodori-TTS·Qwen3-TTS 동작 문제 <a class="header-anchor" href="#irodori-tts・qwen3-ttsが動かない" aria-label="Permalink to &quot;Irodori-TTS·Qwen3-TTS 동작 문제 {#irodori-tts・qwen3-ttsが動かない}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>확인할 내용</th><th>해결 방법</th></tr></thead><tbody><tr><td>Vulkan 지원</td><td>지원 GPU와 드라이버가 필요하며 GPU 드라이버 업데이트</td></tr><tr><td>VRAM 여유</td><td>VRChat·로컬 번역과 공유. VRChat 화질 낮추기, CPU 번역, VOICEVOX 사용</td></tr><tr><td>첫 읽기만 느림</td><td>모델을 불러오므로 시작 직후·목소리 변경 직후 잠시 대기</td></tr><tr><td>전환이 느림</td><td>Irodori·Qwen은 동시에 하나만 로드. 출력 언어 변경 시 몇 초 걸릴 수 있음</td></tr></tbody></table><h2 id="翻訳されない" tabindex="-1">번역이 안 됨 <a class="header-anchor" href="#翻訳されない" aria-label="Permalink to &quot;번역이 안 됨 {#翻訳されない}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>확인할 내용</th><th>해결 방법</th></tr></thead><tbody><tr><td>언어 조합</td><td>말하는 언어와 출력 언어가 다를 때만 번역</td></tr><tr><td>준비된 엔진</td><td>설정 &gt; 번역에서 Azure 키 입력 또는 PLaMo·TranslateGemma 다운로드(<a href="/Mutelink-releases/ko/compare/translation">비교</a>)</td></tr><tr><td>Azure 키·지역</td><td><a href="/Mutelink-releases/ko/guide/azure-translator#うまくいかないとき">Azure 설정 문제 해결</a> 참고</td></tr><tr><td>번역됐는데 소리가 없음</td><td>번역문 읽기는 <a href="/Mutelink-releases/ko/about/supporter">후원판</a>과 지원 목소리(일본어 외에는 Qwen) 필요</td></tr></tbody></table><p>번역 실패 시 원인을 표시하고 원문을 채팅창으로만 보냅니다.</p><h2 id="聞こえた声が出ない" tabindex="-1">들리는 음성이 안 나옴 <a class="header-anchor" href="#聞こえた声が出ない" aria-label="Permalink to &quot;들리는 음성이 안 나옴 {#聞こえた声が出ない}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>확인할 내용</th><th>해결 방법</th></tr></thead><tbody><tr><td>듣기 켜짐</td><td>메인 👂 버튼으로 시작</td></tr><tr><td>VRChat 실행</td><td>설정 &gt; 듣기 &gt; 들리는 음성에 지정한 앱(기본 VRChat)만 캡처하며 실행 전에는 대기</td></tr><tr><td>모델 다운로드</td><td>설정 &gt; 기타 &gt; 모델과 용량 확인</td></tr><tr><td>BGM 계속 재생</td><td>발화 경계를 못 찾을 수 있으므로 설정 &gt; 듣기 &gt; 들리는 음성에서 감지 엄격도 높이기</td></tr><tr><td>내 읽기가 안 나옴</td><td>Mutelink 자신의 읽기는 캡처하지 않음</td></tr></tbody></table><h2 id="vrの中に画面が出ない" tabindex="-1">VR 안에 화면이 안 나옴 <a class="header-anchor" href="#vrの中に画面が出ない" aria-label="Permalink to &quot;VR 안에 화면이 안 나옴 {#vrの中に画面が出ない}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>확인할 내용</th><th>해결 방법</th></tr></thead><tbody><tr><td>SteamVR 실행</td><td>몇 초마다 자동 재연결. SteamVR 실행 상태에서 Mutelink 재시작</td></tr><tr><td>다른 오버레이 앱</td><td>다른 SteamVR 오버레이와 버튼 할당 충돌 확인</td></tr><tr><td>손등에 표시</td><td><a href="/Mutelink-releases/ko/about/supporter">후원판 커스터마이즈 확장</a> 필요. 없으면 시야에 표시</td></tr></tbody></table><h2 id="アプリが起動しない" tabindex="-1">앱이 시작되지 않음 <a class="header-anchor" href="#アプリが起動しない" aria-label="Permalink to &quot;앱이 시작되지 않음 {#アプリが起動しない}&quot;">​</a></h2><p>최신 버전을 다시 설치하고 Windows를 재시작하세요. 계속 실패하면 BOOTH 또는 개발자의 X(<a href="https://x.com/nktssbat" target="_blank" rel="noreferrer">@nktssbat</a>, <a href="https://x.com/yuki54625" target="_blank" rel="noreferrer">@yuki54625</a>)로 알려 주세요.</p>',31)])])}const y=d(i,[["render",l]]);export{f as __pageData,y as default};
